        _ = lockfile.buffers.resolutions.clearRetainingCapacity();
        _ = try lockfile.buffers.resolutions.appendSlice(allocator, final_cur);
        return report;
}

pub fn effectiveNpmRange(lockfile: *const Lockfile, dep_id: DependencyID, dep: Dependency) ?Dependency.Version {
        if (effectiveVersion(lockfile, dep_id, dep)) |ver| {
            _ = &ver;
            if ((ver.tag == .npm)) {
                return ver;
            }
        }
        return null;
}

pub fn effectiveVersion(lockfile: *const Lockfile, dep_id: DependencyID, dep: Dependency) ?Dependency.Version {
        _ = &dep_id;
        var version = (if ((dep.behavior.isWorkspace() or ((dep.version.tag == .npm) and (if (@typeInfo(@TypeOf(dep.version)) == .@"enum") @intFromEnum(dep.version) else dep.version.value).npm.is_alias))) dep.version else ((lockfile.overrides.get(dep.name_hash)) orelse (dep.version)));
        _ = &version;
        if ((version.tag == .catalog)) {
            if (lockfile.catalogs.get(lockfile, (if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).catalog, (if (@typeInfo(@TypeOf(dep)) == .@"enum" or @typeInfo(@TypeOf(dep)) == .@"union") @tagName(dep) else dep.name))) |cat| {
                _ = &cat;
                version = cat.version;
            } else {
                return null;
            }
        }
        return version;
}

pub fn reachable(allocator: Allocator, lockfile: *const Lockfile, resolutions: []const PackageID, frozen_below: ?PackageID) !DynamicBitSet {
        var opts = reachable_mod.Options.all(0);
        _ = &opts;
        opts.bundled = (frozen_below == null);
        return reachable_mod.packages(allocator, lockfile, resolutions, opts);
}

pub fn dedupeBeforeInstall(manager: *PackageManager, load_result: *const Lockfile.LoadResult) !void {
        const quiet = (manager.options.log_level == .silent);
        switch (load_result.*) {
.not_found => {
if ((!quiet)) {
            _ = Output.errGeneric("missing lockfile, nothing to dedupe", .{});
            _ = Output.note("run 'bun install' first", .{});
        }
        _ = Global.exit(1);
},
.err => |cause| {
if (migration.reportedUnsupportedLockfileVersion(cause)) {
            _ = Global.exit(1);
        }
        if ((!quiet)) {
            _ = Output.errGeneric("failed to {s} lockfile: {s}", .{ @tagName(cause.step), @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
            _ = printLogErrors(manager.log);
        }
        _ = Global.crash();
},
.ok => {

},
}
        var empty_root = true;
        _ = &empty_root;
        if (manager.lockfile.rootPackage()) |root| {
            _ = &root;
            if ((root.dependencies.len > 0)) {
                empty_root = false;
            }
        }
        if (empty_root) {
            if (try packageJsonDeclaresDependencies(manager)) {
                _ = refuseOutOfDate(manager);
            }
            var report = Report.init(manager.allocator, manager.lockfile.packages.len);
            _ = &report;
            defer {
            _ = report.deinit();
            }
            _ = reportAlreadyDeduplicated(manager, (&report));
        }
}

pub fn printLogErrors(log: *logger.Log) void {
        if (log.hasErrors()) {
            _ = (blk_catch_0: { break :blk_catch_0 ((log.print(Output.errorWriter())) catch |__ce_0| { _ = &__ce_0;  }); });
        }
}

pub fn packageJsonDeclaresDependencies(manager: *PackageManager) !bool {
        const quiet = (manager.options.log_level == .silent);
        const log = manager.log;
        const path: []const u8 = PackageManager.root_package_json_path;
        const json_res = manager.workspace_package_json_cache.getWithPath(manager.allocator, log, path, .{});
        switch (json_res) {
.entry => |entry| {
var temp_lf: Lockfile = undefined;
        _ = &temp_lf;
        _ = temp_lf.initEmpty(manager.allocator);
        defer {
        _ = temp_lf.deinit();
        }
        var root: Lockfile.Package = .{};
        _ = &root;
        var resolver: void = undefined;
        _ = &resolver;
        _ = (blk_catch_1: { break :blk_catch_1 ((Lockfile.Package.parseWithJSON((&root), (&temp_lf), manager, manager.allocator, log, (&entry.source), entry.root, void, (&resolver), Features.main)) catch |e| { _ = &e; if ((!quiet)) {
            _ = printLogErrors(log);
        }
        return e; }); });
        return (root.dependencies.len > 0);
},
.read_err => |e| {
if ((!quiet)) {
            _ = printLogErrors(log);
            _ = Output.err(e, "failed to read {s}", .{ path });
        }
        _ = Global.exit(1);
},
.parse_err => |e| {
if ((!quiet)) {
            _ = printLogErrors(log);
            _ = Output.err(e, "failed to parse {s}", .{ path });
        }
        _ = Global.exit(1);
},
}
}

pub fn refuseOutOfDate(manager: *const PackageManager) noreturn {
        if ((manager.options.log_level != .silent)) {
            _ = Output.errGeneric("bun.lock does not match package.json, nothing to dedupe", .{});
            _ = Output.note("run 'bun install' first", .{});
            _ = Output.flush();
        }
        _ = Global.exit(1);
}

pub fn reportAlreadyDeduplicated(manager: *const PackageManager, report: *const Report) noreturn {
        if ((manager.options.log_level != .silent)) {
            _ = printKept(report.kept.items);
            if (manager.options.do.summary) {
                if ((report.kept.items.len > 0)) {
                    _ = Output.pretty("\n", .{});
                }
                _ = Output.pretty("🎉 <green>No duplicates<r> <d>— checked {d} package{s}, every one already resolves to a single version<r> ", .{ report.checked, plural(report.checked) });
                _ = Output.printStartEndStdout(bun.cli.start_time, std.time.nanoTimestamp());
                _ = Output.pretty("\n", .{});
            }
            _ = Output.flush();
        }
        _ = Global.exit(0);
}

pub fn printKept(kept: []const []u8) void {
        for (cp_iter_slice(kept)) |line| {
            _ = &line;
            _ = Output.prettyln("  <d>kept<r> {s}", .{ line });
        }
}

pub fn printWouldRemove(manager: *const PackageManager, report: *const Report) void {
        _ = printRows(report);
        if ((!manager.options.do.summary)) {
            return;
        }
        const n = report.rows.items.len;
        _ = Output.pretty("\n<b>{d}<r> duplicate version{s} can be removed <d>(checked {d} package{s})<r> ", .{ n, plural(n), report.checked, plural(report.checked) });
        _ = Output.printStartEndStdout(bun.cli.start_time, std.time.nanoTimestamp());
        _ = Output.pretty("\n", .{});
}

pub fn printRows(report: *const Report) void {
        const glyph: []const u8 = (if (Output.enable_ansi_colors_stdout) "↳" else "~");
        const arrow: []const u8 = (if (Output.enable_ansi_colors_stdout) "→" else "->");
        for (report.rows.items) |row| {
            _ = &row;
            if ((row.to_ver.len == 0)) {
                _ = Output.prettyln("<cyan>{s}<r> <b>{s}<r> <d>{s}<r>", .{ glyph, (if (@typeInfo(@TypeOf(row)) == .@"enum" or @typeInfo(@TypeOf(row)) == .@"union") @tagName(row) else row.name), row.from_ver });
            } else {
                _ = Output.prettyln("<cyan>{s}<r> <b>{s}<r> <d>{s} {s}<r> <b>{s}<r>", .{ glyph, (if (@typeInfo(@TypeOf(row)) == .@"enum" or @typeInfo(@TypeOf(row)) == .@"union") @tagName(row) else row.name), row.from_ver, arrow, row.to_ver });
            }
        }
        _ = printKept(report.kept.items);
}

pub fn printDedupeSummary(manager: *const PackageManager, installed: u32, start_time: i128) void {
        const report = ((manager.dedupe_report) orelse { return; });
        if ((manager.options.log_level == .silent)) {
            return;
        }
        _ = printRows((&report));
        if ((!manager.options.do.summary)) {
            _ = Output.flush();
            return;
        }
        const n = report.rows.items.len;
        _ = Output.pretty("\n<b>{d}<r> duplicate version{s} removed", .{ n, plural(n) });
        if ((installed > 0)) {
            _ = Output.pretty(", <b>{d}<r> package{s} installed", .{ installed, plural(installed) });
        }
        _ = Output.pretty(" <d>(checked {d} package{s})<r> ", .{ report.checked, plural(report.checked) });
        _ = Output.printStartEndStdout(start_time, std.time.nanoTimestamp());
        _ = Output.pretty("\n", .{});
        _ = Output.flush();
}

pub fn dedupeAfterDiffer(manager: *PackageManager) void {
        const quiet = (manager.options.log_level == .silent);
        if (manager.summary.changesDependencies()) {
            _ = refuseOutOfDate(manager);
        }
        var report = bun.handleOom(dedupeLockfile(manager.allocator, manager.lockfile, null));
        _ = &report;
        if ((report.rows.items.len == 0)) {
            defer {
            _ = report.deinit();
            }
            _ = reportAlreadyDeduplicated(manager, (&report));
        }
        if (manager.options.dry_run) {
            defer {
            _ = report.deinit();
            }
            if ((!quiet)) {
                _ = printWouldRemove(manager, (&report));
                _ = Output.prettyln("  <cyan>bun dedupe<r>", .{});
                _ = Output.flush();
            }
            _ = Global.exit((if (manager.options.dedupe_check) 1 else 0));
        }
        if ((!manager.options.do.save_lockfile)) {
            defer {
            _ = report.deinit();
            }
            if ((!quiet)) {
                const why: []const u8 = (if ((!manager.options.enable.frozen_lockfile)) "--no-save was passed" else (if (manager.options.local_package_features.dev_dependencies) "--frozen-lockfile was passed" else "--production implies --frozen-lockfile"));
                _ = printWouldRemove(manager, (&report));
                _ = Output.flush();
                const n = report.rows.items.len;
                _ = Output.prettyErrorln("<r><red>error<r><d>:<r> {d} duplicate version{s} can be removed, but {s}", .{ n, plural(n), why });
                const pronoun: []const u8 = (if ((n == 1)) "it" else "them");
                _ = Output.note("run 'bun dedupe' to remove {s}, or 'bun dedupe --check' in CI", .{ pronoun });
                _ = Output.flush();
            }
            _ = Global.exit(1);
        }
        manager.dedupe_report = report;
        manager.options.enable.force_save_lockfile = true;
}

pub fn collapseAppended(manager: *PackageManager, loaded_package_count: usize) void {
        const lockfile = manager.lockfile;
        if ((lockfile.packages.len <= loaded_package_count)) {
            return;
        }
        var report = bun.handleOom(dedupeLockfile(manager.allocator, lockfile, @intCast(loaded_package_count)));
        _ = &report;
        defer {
        _ = report.deinit();
        }
}
